INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'pe-simplificado',
  'PE simplificado: qual infraestrutura o Fundo Travessia deve comprar',
  'private-equity',
  'Compare três oportunidades de infraestrutura e recomende uma aquisição ao comitê de investimentos de um fundo.',
  'Recomende um projeto ao comitê, testando as premissas e revendo a decisão se a investigação mudar os números.',
  $$Você trabalha no Fundo Travessia, que está analisando três oportunidades de infraestrutura: energia solar (Ipê), data centers (Cedro) e torres de telecomunicações (Jacarandá). Renata, sócia do fundo, apresenta o desafio: “Temos até R$ 150 milhões e vamos escolher uma única aquisição nesta rodada. Precisamos recuperar o investimento em até cinco anos, com TIR projetada de pelo menos 18% ao ano. Entre as oportunidades que atendam a esses limites, queremos aquela que crie mais valor em reais, medido pelo VPL. O dinheiro que sobrar ficará em reserva: não temos outra aquisição disponível nesta rodada. Antes de decidir, precisamos testar as premissas. Se a investigação mudar os números, quero que você reveja sua recomendação.”$$,
  $${"resumo": "Private Equity compra participações em empresas, ajuda a melhorar o negócio durante alguns anos e depois vende a participação. O retorno vem da diferença entre o que o fundo pagou e o que recebe na saída. Neste case, você analisa três oportunidades de infraestrutura e recomenda uma ao comitê de investimentos.", "links": [], "cards": [{"titulo": "O que faz um fundo de Private Equity", "texto": "O fundo reúne dinheiro de investidores, compra participações em empresas ou projetos que não estão na bolsa e acompanha a gestão até vender a participação.", "naPratica": "A equipe analisa oportunidades, negocia a compra e acompanha o desempenho depois do investimento."}, {"titulo": "Retorno, prazo e valor criado", "texto": "Um mesmo investimento pode ser medido de formas diferentes: quantas vezes o capital se multiplica (MOIC), qual o retorno anual considerando o tempo (TIR) e quanto valor é criado hoje em reais (VPL).", "naPratica": "Cada indicador responde a uma pergunta diferente. Por isso o fundo define antes qual deles decide a escolha."}, {"titulo": "Due diligence", "texto": "É a investigação feita antes da compra para testar as informações do vendedor: contratos, equipamentos, licenças, finanças e outros pontos que sustentam a tese.", "naPratica": "Uma descoberta na due diligence pode exigir mais capital ou reduzir o retorno esperado e mudar a recomendação."}, {"titulo": "Tese de investimento", "texto": "Uma boa tese tem duas partes: o que torna a oportunidade atrativa e o que poderia impedir esse resultado.", "naPratica": "Ao apresentar uma recomendação, mostre o motivo de investir e os riscos que você testou."}], "comoSeEntra": {"ondeSeTrabalha": "Gestoras de fundos de Private Equity, bancos de investimento, consultorias e áreas de investimento de grandes empresas.", "formacoes": "Economia, Administração, Engenharia e Ciências Contábeis são formações comuns.", "vagas": "Estágio em gestoras de fundos, em bancos de investimento e em consultorias financeiras.", "oQueAjuda": "Excel, noções de valuation, leitura de demonstrações financeiras e escrita objetiva de recomendações.", "quandoRecrutam": "Muitos programas abrem uma vez por ano. Acompanhe as páginas de carreira das empresas."}}$$::jsonb,
  'publicado',
  3
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
('pe-simplificado-indicadores', 'MOIC, TIR e VPL: três formas de olhar o retorno', 'glossario', 'private-equity', 'Três indicadores que respondem a perguntas diferentes sobre um investimento.', $$**MOIC** mostra quantas vezes o fundo recebe o capital investido (valor recebido ÷ valor investido) e não considera o tempo de espera. **TIR** é o retorno anualizado, considera o tempo e os juros compostos. **VPL** é o valor criado hoje, em reais: valor presente dos recebimentos menos o investimento inicial, usando uma taxa de desconto que representa a remuneração exigida. Um projeto pode ter o maior MOIC ou a maior TIR e, ainda assim, não ser o que cria mais valor em reais.$$, NULL, 5, '["pe-simplificado"]'::jsonb),
('pe-simplificado-due-diligence', 'Due diligence: testar a tese antes de comprar', 'artigo', 'private-equity', 'O que se investiga antes de uma aquisição e como isso muda os números.', $$Antes de comprar, o fundo verifica se as informações do vendedor se sustentam. Em infraestrutura, isso inclui contratos de venda ou locação (prazo, cláusulas de cancelamento, capacidade de pagamento dos clientes), situação de licenças e direitos de uso de terrenos, estado dos equipamentos e da manutenção, e a capacidade de conectar ou ampliar a operação. Quando a investigação revela gastos adicionais, o investimento sobe e os indicadores de retorno precisam ser recalculados. Retornos projetados nunca são garantidos.$$, NULL, 6, '["pe-simplificado"]'::jsonb),
('pe-simplificado-mandato', 'Como ler o mandato de um fundo', 'artigo', 'private-equity', 'Prazo, retorno mínimo e critério de escolha definem quais projetos podem ser recomendados.', $$O mandato diz o que o fundo pode e quer fazer: quanto capital tem, em quanto tempo precisa recuperá-lo, qual retorno anual mínimo exige e qual critério usa para escolher entre as opções. Primeiro, separe as oportunidades que atendem a todos os limites. Depois, compare apenas essas pelo critério de escolha definido. Um projeto que se destaca em um indicador, mas não cumpre um limite do mandato, não pode ser recomendado.$$, NULL, 4, '["pe-simplificado"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO checkpoints (id, case_id, "order", stage, title, description, points, task_ids) VALUES
('pe-cp-1', 'pe-simplificado', 1, 'entenda', 'Entenda o papel do Private Equity', 'Conheça como um fundo escolhe e acompanha investimentos antes de analisar as três oportunidades de infraestrutura.', 15, '[]'::jsonb),
('pe-cp-2', 'pe-simplificado', 2, 'conteudos', 'Conteúdos do case', 'Leia todos os conteúdos de apoio do case antes de seguir para os projetos.', 10, '[]'::jsonb),
('pe-cp-3', 'pe-simplificado', 3, 'treino', 'Conheça os projetos', 'Escolha os maiores atrativos de Ipê, Cedro e Jacarandá e teste cada tese com uma pergunta de risco.', 30, '["pe-task-ipe", "pe-task-cedro", "pe-task-jacaranda"]'::jsonb),
('pe-cp-4', 'pe-simplificado', 4, 'treino', 'MOIC, TIR e VPL', 'Pratique os três indicadores com exemplos pequenos antes de comparar os projetos.', 25, '["pe-task-indicadores"]'::jsonb),
('pe-cp-5', 'pe-simplificado', 5, 'situacao', 'Compare e escolha', 'Use o mandato do fundo para escolher o projeto que levará para a análise detalhada.', 30, '["pe-task-comparar"]'::jsonb),
('pe-cp-6', 'pe-simplificado', 6, 'situacao', 'A reviravolta', 'Acompanhe a due diligence do projeto escolhido, recalcule os indicadores e decida de novo.', 35, '["pe-task-reviravolta", "pe-task-decisao"]'::jsonb),
('pe-cp-7', 'pe-simplificado', 7, 'defesa', 'Comitê de investimentos', 'Apresente a recomendação final e explique o que mudou com a descoberta.', 40, '["pe-task-comite"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
('pe-task-ipe', 'pe-simplificado', 'pe-cp-3', 'Projeto Ipê — Energia solar',
  $$O Ipê reúne parques solares que vendem energia para empresas. O plano é ampliar a capacidade de geração. Escolha os dois atrativos que mais pesam na sua análise, em ordem de importância. Depois, responda apenas à pergunta de risco de cada atrativo escolhido. Uma tese precisa de duas partes: o que torna o projeto atrativo e o que pode impedir esse resultado.$$,
  $$[{"id": "atrativo_1", "tipo": "opcao", "rotulo": "Ipê — primeiro maior atrativo (escolha dois atrativos diferentes, em ordem de importância)", "obrigatorio": true, "opcoes": ["A. Contratos de venda de energia de longo prazo ajudam a prever as receitas.", "B. A região possui condições favoráveis para geração solar.", "C. Terrenos próximos permitem ampliar os parques existentes.", "D. Os parques em operação já possuem histórico de geração e custos."]}, {"id": "atrativo_2", "tipo": "opcao", "rotulo": "Ipê — segundo maior atrativo", "obrigatorio": true, "opcoes": ["A. Contratos de venda de energia de longo prazo ajudam a prever as receitas.", "B. A região possui condições favoráveis para geração solar.", "C. Terrenos próximos permitem ampliar os parques existentes.", "D. Os parques em operação já possuem histórico de geração e custos."]}, {"id": "risco_a", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo A) Qual risco mais diretamente enfraquece o atrativo A?", "obrigatorio": false, "opcoes": ["Um comprador relevante pode deixar de pagar pela energia contratada.", "A expansão pode exigir novos equipamentos.", "Os parques podem precisar de manutenção adicional.", "O terreno destinado à expansão pode precisar de licenças."]}, {"id": "risco_b", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo B) Qual risco mais diretamente enfraquece o atrativo B?", "obrigatorio": false, "opcoes": ["Um comprador pode pedir prazo maior de pagamento.", "Os estudos podem ter superestimado a incidência solar e a geração esperada.", "A expansão pode depender de licenças.", "Os equipamentos podem exigir manutenção mais cara."]}, {"id": "risco_c", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo C) Qual risco mais diretamente enfraquece o atrativo C?", "obrigatorio": false, "opcoes": ["Um cliente atual pode atrasar pagamentos.", "Os equipamentos existentes podem precisar de manutenção.", "A rede elétrica local pode não comportar a energia adicional.", "A geração dos parques atuais pode variar entre os meses."]}, {"id": "risco_d", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo D) Qual risco mais diretamente enfraquece o atrativo D?", "obrigatorio": false, "opcoes": ["A expansão pode precisar de novos contratos de venda.", "O terreno vizinho pode exigir licenciamento.", "Novos parques podem enfrentar condições diferentes.", "O histórico pode esconder manutenção adiada e deterioração dos equipamentos."]}]$$::jsonb,
  NULL,
  $${"observacao": "A ordem dos atrativos expressa preferência, sem gabarito único. As perguntas de risco têm resposta correta, relativa ao atrativo escolhido.", "referencias": {"risco_a": "Um comprador relevante pode deixar de pagar pela energia contratada.", "risco_b": "Os estudos podem ter superestimado a incidência solar e a geração esperada.", "risco_c": "A rede elétrica local pode não comportar a energia adicional.", "risco_d": "O histórico pode esconder manutenção adiada e deterioração dos equipamentos."}, "feedbackPorRisco": {"risco_a": "Um contrato longo ajuda a prever receitas, mas não garante o recebimento. Se o comprador não conseguir pagar, a previsibilidade fica comprometida.", "risco_b": "A tese depende de transformar as condições naturais em geração efetiva. Se os estudos superestimaram o recurso solar, a produção pode ficar abaixo do previsto.", "risco_c": "Ter terreno não basta para expandir. O projeto também precisa conseguir conectar e entregar a energia adicional à rede.", "risco_d": "Custos históricos baixos também podem refletir manutenção que deixou de ser feita. É preciso verificar se o desempenho passado é sustentável."}, "padraoFeedback": {"acerto": "Boa! ✨ Você conectou o risco ao atrativo escolhido.", "erro": "Vamos olhar essa conexão juntas 💜 A resposta é a opção [número]."}}$$::jsonb),
('pe-task-cedro', 'pe-simplificado', 'pe-cp-3', 'Projeto Cedro — Data centers',
  $$O Cedro reúne instalações que abrigam servidores de empresas. Seus clientes precisam de energia, refrigeração e conectividade contínuas. Escolha os dois atrativos que mais pesam na sua análise, em ordem de importância. Depois, responda apenas à pergunta de risco de cada atrativo escolhido. Uma tese precisa de duas partes: o que torna o projeto atrativo e o que pode impedir esse resultado.$$,
  $$[{"id": "atrativo_1", "tipo": "opcao", "rotulo": "Cedro — primeiro maior atrativo (escolha dois atrativos diferentes, em ordem de importância)", "obrigatorio": true, "opcoes": ["A. Clientes que instalam equipamentos tendem a evitar os custos e a complexidade de uma mudança.", "B. O crescimento do uso de nuvem e inteligência artificial pode ampliar a demanda.", "C. Uma área disponível permite construir um novo módulo.", "D. Contratos permitem repassar parte dos custos de energia aos clientes."]}, {"id": "atrativo_2", "tipo": "opcao", "rotulo": "Cedro — segundo maior atrativo", "obrigatorio": true, "opcoes": ["A. Clientes que instalam equipamentos tendem a evitar os custos e a complexidade de uma mudança.", "B. O crescimento do uso de nuvem e inteligência artificial pode ampliar a demanda.", "C. Uma área disponível permite construir um novo módulo.", "D. Contratos permitem repassar parte dos custos de energia aos clientes."]}, {"id": "risco_a", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo A) Qual risco mais diretamente enfraquece o atrativo A?", "obrigatorio": false, "opcoes": ["A expansão pode custar mais que o previsto.", "Falhas recorrentes de disponibilidade podem levar clientes a sair, apesar do custo da mudança.", "A energia pode ficar mais cara.", "Novos equipamentos podem exigir mais refrigeração."]}, {"id": "risco_b", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo B) Qual risco mais diretamente enfraquece o atrativo B?", "obrigatorio": false, "opcoes": ["A manutenção pode ficar mais cara.", "Os contratos podem ter reajustes em datas diferentes.", "Novos concorrentes podem ampliar a oferta mais rapidamente que a demanda.", "O novo módulo pode precisar de adequações elétricas."]}, {"id": "risco_c", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo C) Qual risco mais diretamente enfraquece o atrativo C?", "obrigatorio": false, "opcoes": ["Pode não haver energia disponível para atender à expansão no prazo previsto.", "Clientes atuais podem renegociar condições de pagamento.", "A manutenção das instalações atuais pode ficar mais cara.", "Os contratos podem limitar repasses de custos."]}, {"id": "risco_d", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo D) Qual risco mais diretamente enfraquece o atrativo D?", "obrigatorio": false, "opcoes": ["A procura por espaço pode crescer menos que o previsto.", "A instalação pode precisar de mais refrigeração.", "Um cliente pode reduzir sua área contratada.", "Limites e atrasos contratuais podem impedir o repasse integral do aumento de custos."]}]$$::jsonb,
  NULL,
  $${"observacao": "A ordem dos atrativos expressa preferência, sem gabarito único. As perguntas de risco têm resposta correta, relativa ao atrativo escolhido.", "referencias": {"risco_a": "Falhas recorrentes de disponibilidade podem levar clientes a sair, apesar do custo da mudança.", "risco_b": "Novos concorrentes podem ampliar a oferta mais rapidamente que a demanda.", "risco_c": "Pode não haver energia disponível para atender à expansão no prazo previsto.", "risco_d": "Limites e atrasos contratuais podem impedir o repasse integral do aumento de custos."}, "feedbackPorRisco": {"risco_a": "O custo de mudança pode favorecer a permanência, mas não compensa um serviço que falha repetidamente. A qualidade operacional sustenta essa tese.", "risco_b": "Um mercado em crescimento não garante bons resultados para todos. Se a oferta crescer mais rápido, pode haver menor ocupação ou pressão sobre preços.", "risco_c": "A área física é apenas uma parte da expansão. Sem fornecimento elétrico suficiente, o novo módulo pode não operar como planejado.", "risco_d": "É preciso examinar como o repasse funciona. Limites ou atrasos podem deixar parte do aumento de custos com o projeto."}, "padraoFeedback": {"acerto": "Boa! ✨ Você conectou o risco ao atrativo escolhido.", "erro": "Vamos olhar essa conexão juntas 💜 A resposta é a opção [número]."}}$$::jsonb),
('pe-task-jacaranda', 'pe-simplificado', 'pe-cp-3', 'Projeto Jacarandá — Torres de telecomunicações',
  $$O Jacarandá reúne torres onde operadoras instalam antenas de telefonia e internet móvel. Uma mesma torre pode atender a mais de uma operadora. Escolha os dois atrativos que mais pesam na sua análise, em ordem de importância. Depois, responda apenas à pergunta de risco de cada atrativo escolhido. Uma tese precisa de duas partes: o que torna o projeto atrativo e o que pode impedir esse resultado.$$,
  $$[{"id": "atrativo_1", "tipo": "opcao", "rotulo": "Jacarandá — primeiro maior atrativo (escolha dois atrativos diferentes, em ordem de importância)", "obrigatorio": true, "opcoes": ["A. Uma torre pode receber novos clientes sem exigir a construção de outra estrutura.", "B. Contratos de locação de longo prazo ajudam a prever as receitas.", "C. Algumas torres estão em locais onde é difícil instalar estruturas concorrentes.", "D. A expansão da cobertura móvel pode aumentar a procura por espaço nas torres."]}, {"id": "atrativo_2", "tipo": "opcao", "rotulo": "Jacarandá — segundo maior atrativo", "obrigatorio": true, "opcoes": ["A. Uma torre pode receber novos clientes sem exigir a construção de outra estrutura.", "B. Contratos de locação de longo prazo ajudam a prever as receitas.", "C. Algumas torres estão em locais onde é difícil instalar estruturas concorrentes.", "D. A expansão da cobertura móvel pode aumentar a procura por espaço nas torres."]}, {"id": "risco_a", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo A) Qual risco mais diretamente enfraquece o atrativo A?", "obrigatorio": false, "opcoes": ["Os contratos podem ter reajustes em datas diferentes.", "Uma operadora pode atrasar pagamentos.", "Algumas estruturas podem exigir reforços caros para receber novas antenas.", "O direito de uso de alguns terrenos pode precisar de renovação."]}, {"id": "risco_b", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo B) Qual risco mais diretamente enfraquece o atrativo B?", "obrigatorio": false, "opcoes": ["Cláusulas de cancelamento podem permitir a retirada de antenas antes do esperado.", "Novas torres podem enfrentar demora no licenciamento.", "Algumas estruturas podem precisar de reforço.", "A manutenção pode ficar mais cara."]}, {"id": "risco_c", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo C) Qual risco mais diretamente enfraquece o atrativo C?", "obrigatorio": false, "opcoes": ["As operadoras podem adiar a instalação de antenas.", "O direito de uso do terreno pode vencer antes dos contratos com as operadoras.", "Algumas antenas podem exigir reforços.", "A empresa pode enfrentar aumento no custo de manutenção."]}, {"id": "risco_d", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o atrativo D) Qual risco mais diretamente enfraquece o atrativo D?", "obrigatorio": false, "opcoes": ["Contratos atuais podem ter regras diferentes de reajuste.", "A manutenção das torres pode ficar mais cara.", "Alguns terrenos podem precisar de renovação contratual.", "As operadoras podem adiar investimentos e instalar menos antenas que o previsto."]}]$$::jsonb,
  NULL,
  $${"observacao": "A ordem dos atrativos expressa preferência, sem gabarito único. As perguntas de risco têm resposta correta, relativa ao atrativo escolhido.", "referencias": {"risco_a": "Algumas estruturas podem exigir reforços caros para receber novas antenas.", "risco_b": "Cláusulas de cancelamento podem permitir a retirada de antenas antes do esperado.", "risco_c": "O direito de uso do terreno pode vencer antes dos contratos com as operadoras.", "risco_d": "As operadoras podem adiar investimentos e instalar menos antenas que o previsto."}, "feedbackPorRisco": {"risco_a": "Compartilhar a torre pode gerar receita adicional, mas depende de capacidade estrutural. Reforços caros podem reduzir o benefício de receber novos clientes.", "risco_b": "O prazo escrito no contrato não basta. Se houver cancelamento antecipado, a receita pode durar menos do que a projeção considera.", "risco_c": "Uma localização valiosa só beneficia o projeto enquanto ele consegue utilizá-la. A perda do terreno pode comprometer a operação e os contratos.", "risco_d": "A procura por espaço depende de as operadoras executarem seus planos. Investimentos adiados podem reduzir ou atrasar a ocupação esperada."}, "padraoFeedback": {"acerto": "Boa! ✨ Você conectou o risco ao atrativo escolhido.", "erro": "Vamos olhar essa conexão juntas 💜 A resposta é a opção [número]."}}$$::jsonb),
('pe-task-indicadores', 'pe-simplificado', 'pe-cp-4', 'MOIC, TIR e VPL na prática',
  $$O MOIC mostra quantas vezes você recebe o capital investido e não considera o tempo de espera (MOIC = valor recebido ÷ valor investido). A TIR, ou IRR, mostra o retorno anualizado, considerando o tempo e os juros compostos. O VPL mede quanto valor o investimento cria hoje, depois de considerar a remuneração exigida (VPL = valor presente dos recebimentos − investimento inicial; o valor presente já estará calculado para você).$$,
  $$[{"id": "moic", "tipo": "opcao", "rotulo": "MOIC: no Projeto Ipê, o fundo investiria R$ 50 milhões e receberia R$ 150 milhões na saída. Qual é o MOIC?", "obrigatorio": true, "opcoes": ["A. 2,0×", "B. 3,0×", "C. 1,5×", "D. 5,0×"]}, {"id": "tir", "tipo": "opcao", "rotulo": "TIR: um investimento começa com R$ 100. Após um ano, vale R$ 110. Após dois anos, chega a R$ 121. Sem aportes ou retiradas, qual foi o retorno anual composto?", "obrigatorio": true, "opcoes": ["A. 21% ao ano", "B. 10,5% ao ano", "C. 10% ao ano", "D. 11% ao ano"]}, {"id": "vpl", "tipo": "opcao", "rotulo": "VPL: um projeto exige R$ 80 milhões hoje. O valor presente de seus recebimentos futuros é R$ 110 milhões. Qual é o VPL?", "obrigatorio": true, "opcoes": ["A. R$ 30 milhões", "B. R$ 110 milhões", "C. R$ 190 milhões", "D. R$ 80 milhões"]}]$$::jsonb,
  NULL,
  $${"referencias": {"moic": "B. 3,0×", "tir": "C. 10% ao ano", "vpl": "A. R$ 30 milhões"}, "explicacoes": {"moic": "150 ÷ 50 = 3,0×. O MOIC usa todo o recebimento, não apenas o lucro: o fundo recuperaria os R$ 50 milhões iniciais e ganharia mais R$ 100 milhões.", "tir": "R$ 100 crescem 10% e viram R$ 110; R$ 110 crescem mais 10% e viram R$ 121. A taxa anual é 10%, e o ganho acumulado é 21%.", "vpl": "110 − 80 = R$ 30 milhões. Esse é o valor criado hoje, além da remuneração já considerada no desconto dos recebimentos."}}$$::jsonb),
('pe-task-comparar', 'pe-simplificado', 'pe-cp-5', 'Compare os projetos e escolha',
  $$Renata, sócia do Fundo Travessia, apresentou o desafio: “Temos até R$ 150 milhões e vamos escolher uma única aquisição nesta rodada. Precisamos recuperar o investimento em até cinco anos, com TIR projetada de pelo menos 18% ao ano. Entre as oportunidades que atendam a esses limites, queremos aquela que crie mais valor em reais, medido pelo VPL. O dinheiro que sobrar ficará em reserva: não temos outra aquisição disponível nesta rodada.” Você já conhece os três indicadores. Qual oportunidade levaria para a análise detalhada?$$,
  $$[{"id": "recomendacao", "tipo": "opcao", "rotulo": "Qual projeto você recomenda priorizar?", "obrigatorio": true, "opcoes": ["A. Ipê", "B. Cedro", "C. Jacarandá"]}]$$::jsonb,
  $${"titulo": "Oportunidades (R$ milhões). Os recebimentos ocorrem integralmente na saída, sem distribuições intermediárias.", "colunas": ["Ipê — Energia", "Cedro — Data centers", "Jacarandá — Torres"], "linhas": [{"rotulo": "Investimento", "celulas": [{"texto": "50", "valor": 50}, {"texto": "100", "valor": 100}, {"texto": "100", "valor": 100}]}, {"rotulo": "Recebimento projetado", "celulas": [{"texto": "150", "valor": 150}, {"texto": "400", "valor": 400}, {"texto": "280", "valor": 280}]}, {"rotulo": "Prazo", "celulas": [{"texto": "3 anos", "valor": 3}, {"texto": "6 anos", "valor": 6}, {"texto": "4 anos", "valor": 4}]}, {"rotulo": "MOIC", "celulas": [{"texto": "3,0×", "valor": 3.0}, {"texto": "4,0×", "valor": 4.0}, {"texto": "2,8×", "valor": 2.8}]}, {"rotulo": "TIR", "celulas": [{"texto": "44,2%", "valor": 44.2}, {"texto": "26,0%", "valor": 26.0}, {"texto": "29,4%", "valor": 29.4}]}, {"rotulo": "VPL", "celulas": [{"texto": "48,6", "valor": 48.6}, {"texto": "72,9", "valor": 72.9}, {"texto": "60,1", "valor": 60.1}]}]}$$::jsonb,
  $${"referencias": {"recomendacao": "C. Jacarandá"}, "notaDeConsulta": "Os VPLs foram calculados a uma taxa de desconto de 15% ao ano. A TIR mínima de 18% é um requisito separado do fundo.", "feedbackPorEscolha": {"A. Ipê": "O Ipê chama atenção: tem MOIC e TIR maiores que o Jacarandá, além de devolver o dinheiro antes. Mas o fundo quer maior VPL entre as opções que atendem ao mandato. O Jacarandá também atende e cria R$ 60,1 milhões, contra R$ 48,6 milhões do Ipê. Ele é a melhor escolha nesta rodada. 💜", "B. Cedro": "Você identificou o maior VPL! Falta considerar o prazo: o Cedro prevê seis anos, mas o fundo permite até cinco. Entre os projetos elegíveis, o Jacarandá tem o maior VPL. Esse cuidado faz parte da decisão. 💜", "C. Jacarandá": "Boa escolha! ✨ O Jacarandá atende ao prazo e à TIR mínima e tem o maior VPL entre as opções elegíveis. O Ipê multiplica mais o capital e tem maior retorno anual, mas cria menos valor em reais nas condições apresentadas."}, "percursos": "A escolha desta etapa define o percurso da etapa seguinte (mesmo se incorreta)."}$$::jsonb),
('pe-task-reviravolta', 'pe-simplificado', 'pe-cp-6', 'A descoberta e o recálculo',
  $$Esta é a due diligence: ela testa as informações antes da compra. Responda apenas ao bloco do projeto que você escolheu na etapa anterior. A equipe terminou a revisão dos outros projetos e não encontrou ajustes que alterem seus números. Todos os retornos continuam sendo projeções.

Se escolheu Ipê: a análise técnica encontrou um problema. Equipamentos precisam ser substituídos antes do previsto. O fundo precisará investir mais R$ 25 milhões na aquisição. O recebimento continua em R$ 150 milhões após três anos. Novo investimento total: R$ 75 milhões.

Se escolheu Cedro: a expansão custa mais do que parecia. A infraestrutura elétrica não atende ao novo módulo. A adequação exigirá mais R$ 40 milhões na aquisição. O recebimento continua em R$ 400 milhões após seis anos. Novo investimento total: R$ 140 milhões.

Se escolheu Jacarandá: nem todas as torres suportam a expansão. Algumas estruturas precisam de reforços para receber novas antenas. O fundo precisará investir mais R$ 40 milhões na aquisição. O recebimento continua em R$ 280 milhões após quatro anos. Novo investimento total: R$ 140 milhões.$$,
  $$[{"id": "recalculo_ipe", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Ipê) Agora seriam investidos R$ 75 milhões para receber R$ 150 milhões. Qual é o novo MOIC?", "obrigatorio": false, "opcoes": ["A. 3,0×", "B. 2,0×", "C. 1,5×", "D. 0,5×"]}, {"id": "recalculo_cedro", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Cedro) O valor presente do recebimento continua em R$ 172,9 milhões, mas o investimento subiu para R$ 140 milhões. Qual é o novo VPL?", "obrigatorio": false, "opcoes": ["A. R$ 72,9 milhões", "B. R$ 40 milhões", "C. R$ 32,9 milhões", "D. R$ 12,9 milhões"]}, {"id": "recalculo_jacaranda", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Jacarandá) Agora seriam investidos R$ 140 milhões para receber R$ 280 milhões. Qual é o novo MOIC?", "obrigatorio": false, "opcoes": ["A. 2,0×", "B. 2,8×", "C. 1,4×", "D. 0,5×"]}]$$::jsonb,
  NULL,
  $${"referencias": {"recalculo_ipe": "B. 2,0×", "recalculo_cedro": "C. R$ 32,9 milhões", "recalculo_jacaranda": "A. 2,0×"}, "explicacoes": {"recalculo_ipe": "150 ÷ 75 = 2,0×. Antes, o capital se multiplicava por três; agora, por dois. O recebimento não mudou, mas precisamos investir mais para alcançá-lo.", "recalculo_cedro": "172,9 − 140 = R$ 32,9 milhões. O investimento adicional de R$ 40 milhões reduziu o VPL no mesmo valor, porque o recebimento e o prazo permaneceram iguais.", "recalculo_jacaranda": "280 ÷ 140 = 2,0×. O fundo receberia duas vezes o capital investido. Antes da descoberta, o MOIC era de 2,8×."}, "padraoFeedback": {"acerto": "Isso! ✨", "erro": "Vamos conferir juntas 💜"}}$$::jsonb),
('pe-task-decisao', 'pe-simplificado', 'pe-cp-6', 'Compare novamente e decida',
  $$Os vendedores não aceitaram reduzir os preços nesta rodada. Com os números revisados, qual projeto você recomenda? Use a parte da tabela correspondente ao percurso do projeto que você escolheu.$$,
  $$[{"id": "decisao_ipe", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Ipê) Com os números revisados do Ipê, qual projeto você recomenda?", "obrigatorio": false, "opcoes": ["A. Ipê", "B. Cedro", "C. Jacarandá"]}, {"id": "decisao_cedro", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Cedro) Com os números revisados do Cedro, qual projeto você recomenda?", "obrigatorio": false, "opcoes": ["A. Ipê", "B. Cedro", "C. Jacarandá"]}, {"id": "decisao_jacaranda", "tipo": "opcao", "rotulo": "(responda apenas se escolheu o Jacarandá) Com os números revisados do Jacarandá, qual projeto você recomenda?", "obrigatorio": false, "opcoes": ["A. Ipê", "B. Cedro", "C. Jacarandá"]}]$$::jsonb,
  $${"titulo": "Números revisados por percurso (R$ milhões). Veja apenas o percurso do projeto que você escolheu. Prazos: Ipê 3 anos, Cedro 6 anos, Jacarandá 4 anos.", "colunas": ["Ipê", "Cedro", "Jacarandá"], "linhas": [{"rotulo": "Percurso Ipê — Investimento", "celulas": [{"texto": "75 (atualizado)", "valor": 75}, {"texto": "100", "valor": 100}, {"texto": "100", "valor": 100}]}, {"rotulo": "Percurso Ipê — MOIC", "celulas": [{"texto": "2,0×", "valor": 2.0}, {"texto": "4,0×", "valor": 4.0}, {"texto": "2,8×", "valor": 2.8}]}, {"rotulo": "Percurso Ipê — TIR", "celulas": [{"texto": "26,0%", "valor": 26.0}, {"texto": "26,0%", "valor": 26.0}, {"texto": "29,4%", "valor": 29.4}]}, {"rotulo": "Percurso Ipê — VPL", "celulas": [{"texto": "23,6", "valor": 23.6}, {"texto": "72,9", "valor": 72.9}, {"texto": "60,1", "valor": 60.1}]}, {"rotulo": "Percurso Cedro — Investimento", "celulas": [{"texto": "50", "valor": 50}, {"texto": "140 (atualizado)", "valor": 140}, {"texto": "100", "valor": 100}]}, {"rotulo": "Percurso Cedro — MOIC", "celulas": [{"texto": "3,0×", "valor": 3.0}, {"texto": "2,86×", "valor": 2.86}, {"texto": "2,8×", "valor": 2.8}]}, {"rotulo": "Percurso Cedro — TIR", "celulas": [{"texto": "44,2%", "valor": 44.2}, {"texto": "19,1%", "valor": 19.1}, {"texto": "29,4%", "valor": 29.4}]}, {"rotulo": "Percurso Cedro — VPL", "celulas": [{"texto": "48,6", "valor": 48.6}, {"texto": "32,9", "valor": 32.9}, {"texto": "60,1", "valor": 60.1}]}, {"rotulo": "Percurso Jacarandá — Investimento", "celulas": [{"texto": "50", "valor": 50}, {"texto": "100", "valor": 100}, {"texto": "140 (atualizado)", "valor": 140}]}, {"rotulo": "Percurso Jacarandá — MOIC", "celulas": [{"texto": "3,0×", "valor": 3.0}, {"texto": "4,0×", "valor": 4.0}, {"texto": "2,0×", "valor": 2.0}]}, {"rotulo": "Percurso Jacarandá — TIR", "celulas": [{"texto": "44,2%", "valor": 44.2}, {"texto": "26,0%", "valor": 26.0}, {"texto": "18,9%", "valor": 18.9}]}, {"rotulo": "Percurso Jacarandá — VPL", "celulas": [{"texto": "48,6", "valor": 48.6}, {"texto": "72,9", "valor": 72.9}, {"texto": "20,1", "valor": 20.1}]}]}$$::jsonb,
  $${"referencias": {"decisao_ipe": "C. Jacarandá", "decisao_cedro": "C. Jacarandá", "decisao_jacaranda": "A. Ipê"}, "feedbackPorEscolha": {"decisao_ipe": {"A. Ipê": "O Ipê continua atendendo aos requisitos, mas seu VPL caiu para R$ 23,6 milhões. O Jacarandá também atende e cria mais valor: R$ 60,1 milhões. Vale comparar as duas opções antes de manter a escolha. 💜", "B. Cedro": "O maior VPL ainda é do Cedro, mas o prazo continua acima dos cinco anos permitidos. A melhor opção elegível é o Jacarandá. 💜", "C. Jacarandá": "Isso! ✨ Ele atende aos requisitos e apresenta o maior VPL entre os projetos elegíveis. Você considerou o objetivo completo do fundo."}, "decisao_cedro": {"A. Ipê": "O Ipê tem maior MOIC e TIR, mas o fundo prioriza o VPL entre as opções elegíveis. O Jacarandá cria R$ 60,1 milhões, contra R$ 48,6 milhões do Ipê. Esse é o ponto que muda a escolha. 💜", "B. Cedro": "O Cedro ainda supera a TIR mínima, mas continua fora do prazo. A adequação elétrica também reduziu seu VPL. O Jacarandá é a melhor escolha nas condições disponíveis. 💜", "C. Jacarandá": "Isso! ✨ Você considerou o mandato completo: o Jacarandá atende aos requisitos e tem maior VPL que o Ipê."}, "decisao_jacaranda": {"A. Ipê": "Boa atualização! ✨ O Jacarandá ainda atende ao mandato, mas seu VPL caiu. Agora, o Ipê é o projeto elegível que mais cria valor.", "B. Cedro": "O Cedro tem o maior VPL, mas não atende ao prazo. A melhor opção elegível agora é o Ipê. 💜", "C. Jacarandá": "O Jacarandá continua acima da TIR mínima, mas isso não basta para vencer. O Ipê também atende ao mandato e tem VPL maior: R$ 48,6 milhões contra R$ 20,1 milhões. Atualizar a escolha faz parte de uma boa análise. 💜"}}}$$::jsonb),
('pe-task-comite', 'pe-simplificado', 'pe-cp-7', 'Comitê de investimentos',
  $$Apresente sua recomendação ao comitê de investimentos do Fundo Travessia. Lembre do mandato: recuperar o investimento em até cinco anos, TIR projetada de pelo menos 18% ao ano e, entre as opções que atendem, maior VPL.$$,
  $$[{"id": "pergunta_1", "tipo": "texto", "rotulo": "Qual projeto você recomenda agora? Explique por que ele atende ao fundo e supera as outras opções. (até 80 palavras)", "obrigatorio": true, "limiteCaracteres": 560}, {"id": "pergunta_2", "tipo": "texto", "rotulo": "Por que a descoberta mudou os retornos? Que verificação ajudaria a identificar esse problema antes da compra? (até 80 palavras)", "obrigatorio": true, "limiteCaracteres": 560}]$$::jsonb,
  NULL,
  $${"orientacaoCorrecao": {"pergunta_1": {"procurar": ["Indicar o projeto correto para o percurso.", "Considerar prazo e TIR mínima.", "Comparar o VPL com o da outra alternativa elegível."], "conclusaoEsperada": {"Ipê": "Jacarandá", "Cedro": "Jacarandá", "Jacarandá": "Ipê"}, "exemploCompleto": "Recomendo o Ipê. Ele exige R$ 50 milhões, prevê saída em três anos e TIR de 44,2%, atendendo ao mandato. Seu VPL de R$ 48,6 milhões supera o Jacarandá revisado, de R$ 20,1 milhões. O Cedro tem maior VPL, mas ultrapassa o prazo de cinco anos.", "feedbackCompleta": "Você conectou os números ao que o fundo pediu — muito bem! ✨ Também explicou por que as outras opções ficam para trás. Sua recomendação está bem fundamentada.", "feedbackSemJustificativa": "Você chegou ao projeto certo! 💜 Para fortalecer sua recomendação, explique também por que ele atende ao prazo e à TIR mínima e como seu VPL se compara ao da outra opção elegível.", "regra": "Personalizar em até três frases: reconhecer um elemento correto, explicar a lacuna e apresentar a conclusão do percurso."}, "pergunta_2": {"procurar": "Explicar que o investimento aumentou sem aumento do recebimento ou redução do prazo e indicar uma verificação pertinente.", "verificacaoPorPercurso": {"Ipê": "Inspeção dos equipamentos e revisão da manutenção e das reposições previstas.", "Cedro": "Estudo da capacidade elétrica e orçamento da infraestrutura necessária ao novo módulo.", "Jacarandá": "Laudos estruturais e análise da capacidade de suportar novas antenas."}, "feedbackCompleta": "Isso! ✨ Mais capital para receber o mesmo valor no mesmo prazo reduz os retornos. A verificação que você propôs também está conectada ao problema encontrado.", "feedbackSemVerificacao": "Você explicou corretamente o efeito nos retornos! 💜 Falta transformar isso em investigação: neste projeto, seria importante verificar [verificação do percurso] antes da compra.", "feedbackIncorreta": "Vamos conectar os pontos 💜 O recebimento e o prazo não mudaram, mas o fundo precisa investir mais. Por isso, MOIC, TIR e VPL diminuem. Para antecipar esse problema, seria importante [verificação do percurso]."}}, "premissas": ["Todos os aportes ocorrem na aquisição, inclusive os gastos adicionais descobertos.", "Há apenas um recebimento final, sem distribuições intermediárias.", "Os valores representam os fluxos da participação do fundo, antes de taxas e remuneração do gestor.", "O fundo escolhe somente uma aquisição; o capital não utilizado permanece em reserva.", "VPLs com taxa de desconto de 15% ao ano; a TIR mínima de 18% é exigência separada.", "Cada percurso é alternativo: atualizar somente o projeto escolhido."], "aviso": "Não tratar retorno projetado como garantido."}$$::jsonb)
ON CONFLICT (id) DO NOTHING;
